package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaHaDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Kariya Daga Dukkan Cutarwa", "Da sunan Allah, wanda babu abin da yake cutar da sunansa a cikin kasa ko a cikin sammai, kuma Shi ne Mai ji, Masani.", "Sau uku kowace safiya da yamma.", "Wanda ya faxi sau uku safe da yamma, babu abin da zai cutar da shi."),
        "dua_raditu_billahi" to DuaText("Jin dadi da Allah a matsayin Ubangiji", "Na yarda da Allah a matsayin Ubangijina, da Musulunci a matsayin addinina, kuma Muhammadu ﷺ a matsayin Annabina.", "Sau uku safe da yamma.", "Ya zama hakki a kan Allah ya yarda da shi a ranar sakamako."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Allah Ya isa)", "Allah Yã isa gare ni. bãbu abin bautãwa fãce Shi. A gare Shi nake dõgara, kuma Shĩ ne Ubangijin Al'arshi, Mabuwãyi.", "Sau bakwai safe da yamma.", "Ayar Alqur'ani; Allah Ya isa ga damuwa duniya da Lahira."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("SubhanAllahi wa bihamdihi", "Tsarki ya tabbata ga Allah kuma dukkan godiya ta tabbata a gare shi.", "Sau dari a rana.", "Duk wanda ya fadi haka sau dari a rana, an gafarta masa zunubansa, ko da kuwa sun kasance kamar kumfar teku."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Babu abin bautawa da gaskiya sai Allah, Shi kadai, ba tare da abokin tarayya ba. Nasa ne mulki kuma gõdiya ta tabbata, kuma Shĩ, a kan kõme, Mai ĩkon yi ne.", "Babban nagarta wajen fadin hakan sau dari a rana.", "Ladan 'yanta bayi goma, da rubuta ayyukan alheri dari, shafe zunubai dari, da kariya daga Shaidan har zuwa yamma."),
        "dua_leaving_mosque" to DuaText("Fitowar Masallacin", "Ya Allah ina rokonka falalarka.", "Lokacin fita daga masallaci da kafar hagu.", "Neman falalar Allah da azurtarsa ​​yayin fita masallaci."),
        "dua_after_adhan" to DuaText("Bayan Sallah", "Ya Allah Ubangijin wannan cikakkar kira da addu'ar da za'a tabbatar, ka baiwa Muhammad ﷺ al-Wasilah da kyawawan halaye, kuma ka daukaka shi zuwa ga Tashin Yabo da Ka alkawarta masa.", "Bayan an gama adhan.", "Duk wanda ya fadi haka za a ba shi ceton Annabi ﷺ a ranar sakamako."),
        "dua_after_salah_istighfar" to DuaText("Bayan Fard Salah", "Ina neman gafarar Allah (sau uku). Ya Allah kaine-As-salam kuma daga gareka amin. Albarkacinka Ya Ma'abucin Girma da Girmamawa.", "Nan take bayan sallama.", "Annabi ﷺ ya karanta wannan bayan kowace sallar farilla."),
        "dua_after_salah_help_dhikr" to DuaText("Ka Taimake Ni Tunawa Da Ka", "Ya Allah ka taimakeni da ambatonka, da gode maka, da kuma bauta maka ta hanya mafi kyau.", "Bayan kowace sallah - Annabi ﷺ ya shawarci Mu'az (RA) da ya yi ta.", "Nasiha ta musamman na Annabi ﷺ - nagarta da dawwama a cikin ibada."),
        "dua_sleep_tasbeeh" to DuaText("Tasbeeh-e-Fatimi kafin Barci", "Tsarki ya tabbata ga Allah (33), godiya ta tabbata ga Allah (33), Allah ne mafi girma (34).", "Kafin barci - Annabi ﷺ ya koya wa Fatimah da Ali (RA).", "Annabi ﷺ yace gara ka bawa."),
        "dua_sleep_qina_adhab" to DuaText("Kariya daga Hukunci", "Ya Allah ka kare ni daga azabarKa ranar da ka tayar da bayinka.", "Sau uku, tare da hannun dama an sanya shi a ƙarƙashin kunci.", "Maida bacci ya zama tunatarwa akan mutuwa da shiri don lahira."),
        "dua_bad_dream" to DuaText("Bayan Mugun Mafarki", "Ina neman tsarin Allah daga Shaidan La'ananne.", "Bayan mafarki mara kyau: bushe-bushewa da sauƙi zuwa hagu sau uku, sannan juya gefe ɗaya.", "Mugun mafarki ba zai cutar da ku ba; kar ka gaya wa kowa game da shi."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ya Hayyu Ya Qayyum", "Ya Rayayye, Ya Majiɓincin kowa! Da rahamar ka nake neman taimako.", "Lokacin da al'amari ya yi nauyi sosai.", "Duk lokacin da wani abu ya baci Annabi ﷺ, sai ya ce haka."),
        "dua_entering_market" to DuaText("Shiga Kasuwa", "Babu abin bautawa da gaskiya sai Allah, Shi kadai, ba tare da abokin tarayya ba. Nasa ne mulki kuma nasa gõdiya take. Yanã rãyarwa, kuma Yanã kashẽwa, kuma Shĩ, Rãyayye ne, kuma bã Ya mutuwa. A hannunsa ne dukan alhħri yake, kuma Shĩ, a kan kõme, Mai ĩkon yi ne.", "Lokacin shiga kasuwa.", "Hadisi ya ambaci lada mai girma akansa (ayyukan alheri miliyan guda)."),
        "dua_adam_forgiveness" to DuaText("Addu'ar Annabi Adam (AS)", "Ya Ubangijinmu, mun zalunci kanmu, kuma idan ba Ka gafarta mana ba, kuma Ka yi mana rahama, lalle mu muna daga cikin masu hasara.", "Addu'ar tuban Adamu da Hauwa (AS).", "Tuba ta farko ta ɗan adam - Allah ya karɓe ta."),
        "dua_abu_bakr" to DuaText("Addu'a ga Abubakar (RA)", "Ya Allah ni na zalunci kaina da yawa, kuma babu mai gafarta zunubai sai kai, don haka ka gafarta mini daga wurinKa, kuma Ka yi mani rahama. Lalle ne Kai, Kai ne Mai gafara, Mai jin kai.", "Annabi ﷺ ya koya wa Abu Bakr as-Siddiq (RA) cewa a cikin sallah (bayan tashahud).", "Addu'ar sunnah domin karshen sallah."),
        "dua_astaghfirullah_atubu" to DuaText("Daily Istighfar", "Ina neman gafarar Allah kuma ina tuba zuwa gare shi.", "Annabi ﷺ ya nemi gafara fiye da sau saba'in a rana.", "Annabi ﷺ ya ce: Ina neman gafarar Allah da tuba gare shi fiye da sau saba'in a rana."),
        "dua_laylatul_qadr" to DuaText("Addu'ar Lailatul Kadri", "Ya Allah Kai Mai gafara ne kuma kana son yin afuwa, don haka ka gafarta mini.", "An karantar da Aisha (RA) don Lailatul Kadr.", "Addu'a ta musamman ga dararen karshe na Ramadan da Lailatul Kadri."),
        "dua_family_coolness" to DuaText("Sanyin Idanu (Mata & Yara)", "Ubangijinmu Ka sanya mana sanyin idanuwanmu daga matan aurenmu da zuriyarmu, kuma Ka sanya mu shugabanni na salihai.", "Addu'ar Alqur'ani ga ma'aurata salihai da 'ya'ya.", "Domin zaman lafiya a gida da ƴaƴan adalai."),
        "dua_righteous_children" to DuaText("Ga Zuri'a Na Gaskiya", "Ubangijina! Ka ba ni zuriya tsarkakakke daga gare Ka. Lalle Kai, Kai ne Mai jin addu'a.", "Addu'ar Annabi Zakariyya (AS).", "Addu'ar Alqur'ani ga masu neman yara."),
        "dua_ibrahim_prayer_family" to DuaText("Masu tsayar da Sallah", "Ubangijina, Ka sanya ni mai tsayar da salla, kuma daga zuriyata. Ya Ubangijinmu Ka Karbi Addu'ata. Ya Ubangijinmu, Ka gafarta mini, da mahaifana, da muminai, a rãnar da ake yin hisabi.", "Addu'ar Annabi Ibrahim (AS) don kansa da zuriyarsa.", "Wanda akafi karantawa a qarshen sallah."),
        "dua_newlywed" to DuaText("Taya Sabbin Ma'aurata murna", "Allah ya jikan ku, ya yi mana salati, ya kuma sada ku da alkhairai.", "Lokacin taya wani murnar aurensu.", "Sunnah taya murnar aure."),
        "dua_before_eating" to DuaText("Kafin Cin Abinci", "Da sunan Allah. (Idan an manta:) Da sunan Allah a farkonsa da karshensa.", "Kafin cin abinci. Idan kun manta, sai ku faɗi ta gaba ɗaya.", "Yin Bismillah yana hana Shaidan raba abinci."),
        "dua_after_eating" to DuaText("Bayan Cin Abinci", "Dukkan godiya ta tabbata ga Allah da ya ciyar da ni wannan kuma ya azurta ni da ita ba tare da wani karfi ko iko daga bangarena ba.", "Bayan an gama cin abinci.", "Zunuban da ya gabata na wanda ya ce an gafarta masa."),
        "dua_host" to DuaText("Ga Mai watsa shiri", "Ya Allah ka yi musu albarka a cikin abin da ka azurta su, ka gafarta musu, ka yi musu rahama.", "Ga mai gida, bayan cin abinci a gidan wani.", "Godiya ga mai gida a tafarkin Sunnah."),
        "dua_breaking_fast" to DuaText("Bayan Buda Azumi", "Kishirwa ta tafi, jijiyoyi sun jike, kuma lada ya tabbata, in Allah Ya so.", "A lokacin buda baki.", "Annabi ﷺ ya fadi haka lokacin da yake buda baki."),
        "dua_new_clothes" to DuaText("Saka Sabbin Tufafi", "Ya Allah duk godiya ta tabbata gareka; Kun tufatar da ni da wannan. Ina rokonka alherinsa da na abin da aka yi dominsa, kuma ina neman tsarinka daga sharrinsa da sharrin abin da aka yi shi dominsa.", "Lokacin sanya sabon tufa (sunanta, kamar riga ko rawani).", "Annabi ﷺ yayi wannan addu'ar lokacin da yake sanye da sabuwar riga. (Duba ta yau da kullun don sutura tana ƙarƙashin 'Samun Tufafi'.)"),
        "dua_rabbana_atina" to DuaText("Mai kyau Duniya da Lahira", "Ya Ubangijinmu ka bamu mai kyau a duniya da mai kyau a lahira, kuma ka kare mu daga azabar wuta.", "Addu'ar Annabi ﷺ ya yawaita.", "Addu'a mai tara duk wani alheri na duniya da Lahira."),
        "dua_rabbi_zidni_ilma" to DuaText("Ƙara Ilimi", "Ya Ubangiji Ka Kara mini ilimi.", "Domin karuwar ilimi.", "Allah ya umurci Annabi ﷺ da cewa a kara masa komai sai ilimi."),
        "dua_musa_sharh_sadr" to DuaText("Bude Kirji (Musa AS)", "Ubangijina Ka shimfida mini kirjina, Ka saukake mini aikina, kuma Ka kwance min kulli daga harshena, domin su fahimci maganata.", "Kafin jarrabawa, magana ko kowane aiki mai wahala.", "Addu'ar Annabi Musa (AS) - natsuwa da kwanciyar hankali a cikin aikin mutum."),
        "dua_la_tuzigh" to DuaText("Dagewar Zuciya", "Ya Ubangijinmu, kada ka karkatar da zukatanmu bayan Ka shiryar da mu, kuma Ka ba mu wata rahama daga gareKa. Lalle Kai ne Mai yawan kyauta.", "Domin haquri akan shiriya.", "Addu'a don tsayawa tsayin daka cikin imani."),
        "dua_ya_muqallib" to DuaText("Ya Mai Juya Zuciya", "Ya mai juyar da zukata, ka tabbatar da zuciyata akan addininka.", "Annabi ﷺ ya yawaita yin wannan dua.", "A cewar Umm Salamah (RA), addu’ar da Annabi ﷺ ya fi yi."),
        "dua_la_tuakhidhna" to DuaText("Ayoyin Karshen Suratul Baqarah", "Ya Ubangijinmu, kada ka kama mu idan mun manta ko muka yi kuskure. Ya Ubangijinmu kada Ka dora mana wani nauyi irin wanda Ka dora a kan wadanda suka gabace mu. Ya Ubangijinmu, kada Ka dora mu da abin da ba za mu iya dauka ba. Ka gafarta mana, ka gafarta mana, ka yi mana rahama. Kai ne Majiɓincinmu, sai ka taimake mu a kan mutãnen nan kãfirai.", "Da daddare kafin barci - ayoyi biyu na ƙarshe na Suratul Baqarah.", "Duk wanda ya karanta ayoyi biyu na karshen Suratul Baqarah da dare, sun isar masa."),
        "dua_visiting_sick" to DuaText("Ziyartar Marasa Lafiya", "Ina rokon Allah Mabuwayi, Ubangijin Al'arshi mabuwayi, Ya yi muku magani.", "Sau bakwai lokacin ziyartar marasa lafiya.", "Idan lokacin mutuwa bai zo ba, Allah zai yi masa magani."),
        "dua_ruqyah_pain" to DuaText("Don Ciwon Jiki", "Ina neman tsarin Allah da ikonSa daga sharrin abin da nake ji da abin da nake tsoro.", "Ka sanya hannunka a inda yake ciwo, ka yi Bismillah sau uku, sannan wannan addu'ar sau bakwai.", "Annabi ﷺ ya koya wa Uthman bn Abil-'As (RA) ciwon."),
        "dua_ruqyah_nabawi" to DuaText("Ruqyah ta Annabi ga Marasa lafiya", "Ya Allah Ubangijin mutane! Ka kawar da cutarwa, ka ba da magani, domin Kai ne Mai warkarwa; babu magani sai maganinka - maganin da ba ya barin rashin lafiya.", "Yayin mika hannu kan mara lafiya.", "Annabi ﷺ ya karanta wannan lokacin da ya ziyarci majinyata daga cikin iyalansa."),
        "dua_kalimat_tammat" to DuaText("Neman mafaka a cikin Kalmomi cikakke", "Ina neman tsari da kalmomin Allah cikakku daga sharrin abin da Ya halitta.", "Lokacin tsayawa a wuri, ko da yamma.", "Duk wanda ya tsaya a wuri ya fadi haka, babu abin da zai cutar da shi har sai ya bar shi."),
        "dua_evil_eye" to DuaText("Kariya ga Yara (Mugun Ido)", "Ina neman tsari a gare ku da cikakkiyar kalmar Allah daga kowane shaidani da kowane irin halitta mai guba, da kuma duk wani ido mai cutarwa.", "Annabi ﷺ ya karanta wannan akan Hasan da Husain (RA).", "Addu'ar Sunnah domin kare yara daga sharrin ido da cutarwa (ga yaro daya a ce 'U'īdhuka')."),
        "dua_seeing_afflicted" to DuaText("Ganin Wani A Cikin Shari'a", "Dukkan godiya ta tabbata ga Allah wanda Ya tseratar da ni daga abin da Ya jarrabe ku da shi, kuma Ya fifita ni a kan mafi yawan halittunSa.", "A kan ganin wani a cikin gwaji (faɗi shi a hankali ga kanka).", "Wanda ya ce an tsare shi daga wannan fitina."),
        "dua_istikhara" to DuaText("Salatin Istikhara", "Ya Allah ina neman nagari da iliminka, ina neman basira da ikonka, kuma ina rokonka falalarka mai girma. Kuna da iko kuma ba ni da kowa; Ka sani ni ban sani ba, kuma Kai ne Masanin gaibi. Ya Allah, idan a cikin iliminka wannan al'amari (kawo shi) alheri ne ga addinina da rayuwata da karshenta, to ka qaddara mini shi, ka sauwake mini, kuma ka albarkace ni da shi. Kuma idan a cikin saninka wannan al'amari ya kasance sharri ne ga addinina, da rayuwata, da karshena, to, ka kawar da shi daga gare ni, kuma ka kau da ni daga gare shi, kuma ka hukunta mini alheri a duk inda ya kasance, to, ka wadatar da ni da shi.", "Bayan raka'a biyu na sallar nafila, domin neman abin da ya dace a cikin wani lamari na halal.", "Annabi ﷺ ya karantar da Sahabbai istikhara a dukkan al'amura kamar yadda ya koya musu surar Alqur'ani."),
    )
}
